// =============================================================================
// LoadQueue.sv —— load 队列的装配层：6 个子队列 + 一点胶水
//
// 对应 Chisel: xiangshan.mem.LoadQueue（src/main/scala/xiangshan/mem/lsqueue/LoadQueue.scala）
//
// 在流水线里的位置：LsqWrapper 里与 StoreQueue 并列；上接 dispatch（enq）、3 条 load 流水
// （ldu.ldin = load_s3 回写、ldld/stld_nuke_query = s1/s2 查询）、2 条 store 地址流水
// （sta.storeAddrIn）、ROB、uncache 总线；下给后端 rollback / replay / 异常地址。
//
// LoadQueue 自己几乎不存状态，真正的活都在 6 个子队列里（都已单独签核，golden 同名例化）：
//   VirtualLoadQueue  —— 按程序序分配 lqIdx 的虚拟队列：入队、写回标记、出队指针 ldWbPtr
//   LoadQueueRAR      —— load→load（RAR）违例检测：查同地址被 probe/release 过的更年轻 load
//   LoadQueueRAW      —— store→load（RAW）违例检测：store 地址到了反查更年轻的 load，发 nuke_rollback
//   LoadQueueReplay   —— 需要重放的 load 的停车场：记原因、等条件满足后选最老的发回 load 流水
//   LqExceptionBuffer —— 从各路异常里挑最老的一条，给 CSR 提供异常虚拟地址（exceptionAddr）
//   LoadQueueUncache  —— MMIO / NC load 的缓冲：发 uncache 请求、收回数据写回、满了发 nack_rollback
// 子队列之间的连线：ldWbPtr（VLQ→RAR/Replay）、lqFull（RAR/RAW→Replay）、uncache 的异常→异常缓冲。
//
// 胶水（xs_LoadQueue_core，全部手写）只有两件事：
//   §1 入口过滤：谁进异常缓冲（标量 load 的 3 路 + 向量反馈里带 FLUSH 的 2 路；uncache 那一路
//      由 LoadQueueUncache 直接给出），谁进 uncache 缓冲（ldin 里 nc_with_data 的不进）；
//   §2 性能事件：3 个子队列的 17 个计数 + full_mask 的 8 种组合 + 两种 rollback，统一打两拍输出。
//
// ★golden 里被 firtool 消掉、因此本文件也不写的东西：XSPerfAccumulate 的累加器（只剩 perf 端口）、
//   QueuePerf 的 _probe 线；exceptionBuffer.req(5).vaNeedExt := true.B 已被折进 LqExceptionBuffer。
//
// 复位域：本层只有 54 个不复位的 perf 打拍寄存器（与 golden 的 io_perf_*_value_REG / _REG_1 一一对应）。
//
// 本文件导航：
//   xs_LoadQueue_core    §1 入口过滤（异常缓冲 / uncache 缓冲）  §2 性能事件（27 个，两拍打出）
//   LoadQueue            golden 同名 wrapper（GENERATED，scripts/gen_lsq.py）：端口表 → 子队列输出线
//                        （<简称>_<端口名去掉 io_>：rar_ / raw_ / replay_ / vlq_ / excbuf_ / uncache_）
//                        → 胶水核例化 → 6 个子队列例化（实例名、端口顺序同 golden）→ 本层输出 assign
// =============================================================================

module xs_LoadQueue_core (
  input  logic       clock,
  // ---- §1 入口过滤 ----
  input  logic [2:0] ldin_valid,          // 3 条 load 流水 s3 的回写
  input  logic [2:0] ldin_isvec,          // 该回写来自向量 load 的一个元素
  input  logic [2:0] ldin_nc_with_data,   // NC load 已经拿到数据（不必再进 uncache 缓冲）
  input  logic [1:0] vecfb_valid,         // 2 路向量 load 反馈
  input  logic [1:0] vecfb_flush,         // 反馈里的 FLUSH 位 = 该向量指令有异常
  output logic [4:0] excbuf_req_valid,    // 异常缓冲的 0..4 号入口（5 号由 uncache 缓冲直接给）
  output logic [2:0] uncache_req_valid,   // uncache 缓冲的 3 个入口
  // ---- §2 性能事件 ----
  input  logic [16:0][5:0] child_perf,   // RAR 2 个、RAW 2 个、Replay 13 个（golden io_perf_0..16）
  input  logic       rar_full,
  input  logic       raw_full,
  input  logic       replay_full,
  input  logic [1:0] nuke_rollback_valid, // RAW 发出的 2 路 rollback
  input  logic       nack_rollback_valid, // uncache 缓冲满了发出的 rollback
  output logic [26:0][5:0] perf_value
);

  localparam int unsigned N_CHILD_PERF = 17;
  localparam int unsigned N_EVENT      = 10;   // full_mask 8 种 + nuke + nack

  // ---------------------------------------------------------------------------
  // §1 入口过滤
  //   异常缓冲收：标量 load 的回写（向量元素的异常走向量反馈，不在这里重复收）；
  //              向量反馈里 FLUSH 置位的那两路（Scala：feedback(VecFeedbacks.FLUSH)）。
  //   uncache 缓冲收：所有回写里还没拿到数据的（MMIO、以及 nc_with_data=0 的 NC load）；
  //              是不是真要进，由 LoadQueueUncache 自己再看 mmio/nc 位判断。
  // ---------------------------------------------------------------------------
  assign excbuf_req_valid[2:0] = ldin_valid & ~ldin_isvec;
  assign excbuf_req_valid[4:3] = vecfb_valid & vecfb_flush;
  assign uncache_req_valid     = ldin_valid & ~ldin_nc_with_data;

  // ---------------------------------------------------------------------------
  // §2 性能事件
  //   事件号（= golden io_perf_<k>_value 的 k）：
  //     0..16   子队列自己的计数（RAR 0-1、RAW 2-3、Replay 4-16），6 位原样透传；
  //     17..24  full_mask = {RAR 满, RAW 满, Replay 满} 等于 0..7 —— 看哪几个子队列同时堵着；
  //     25      RAW 本拍发了 nuke rollback（任一路）；
  //     26      uncache 缓冲本拍发了 nack rollback。
  //   generatePerfEvent 对每个事件打两拍再送出（两级都不复位）；1 位事件在端口上零扩展成 6 位。
  // ---------------------------------------------------------------------------
  logic [2:0]         full_mask;
  logic [N_EVENT-1:0] event_now;

  assign full_mask = {rar_full, raw_full, replay_full};
  for (genvar k = 0; k < 8; k++) begin : g_full_mask_event
    assign event_now[k] = (full_mask == 3'(k));
  end
  assign event_now[8] = |nuke_rollback_valid;
  assign event_now[9] = nack_rollback_valid;

  logic [5:0]         child_perf_d1 [N_CHILD_PERF];
  logic [5:0]         child_perf_d2 [N_CHILD_PERF];
  logic [N_EVENT-1:0] event_d1;
  logic [N_EVENT-1:0] event_d2;

  always_ff @(posedge clock) begin
    for (int k = 0; k < N_CHILD_PERF; k++) begin
      child_perf_d1[k] <= child_perf[k];
      child_perf_d2[k] <= child_perf_d1[k];
    end
    event_d1      <= event_now;
    event_d2      <= event_d1;
  end

  for (genvar k = 0; k < N_CHILD_PERF; k++) begin : g_child_perf_out
    assign perf_value[k] = child_perf_d2[k];
  end
  for (genvar k = 0; k < N_EVENT; k++) begin : g_event_out
    assign perf_value[N_CHILD_PERF + k] = {5'h0, event_d2[k]};
  end

endmodule


